{
  "candidate_edge_types": [
    {
      "name": "USES_PREVIOUSLY_PRODUCED_ARTIFACT_AS_INPUT",
      "definition": "A later agent action consumes, loads, or executes an artifact (such as a source file or module) that was created by an earlier agent action, using that produced artifact as an input to the later action.",
      "source_description": "An agent action that creates or produces an artifact, for example by writing a source file to disk.",
      "target_description": "A later agent action that loads, sources, executes, or otherwise consumes the previously produced artifact."
    },
    {
      "name": "EXECUTION_BLOCKED_BY_PREVIOUSLY_OBSERVED_MISSING_DEPENDENCY",
      "definition": "A subsequent agent action is attempted even though an earlier observation already reported that a required tool, interpreter, or dependency is unavailable, and the action fails on account of that missing dependency.",
      "source_description": "An observation reporting that a required tool, interpreter, or dependency is missing or not available in the environment.",
      "target_description": "A later agent action that requires the missing dependency and consequently fails (for example, with a command-not-found error)."
    },
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure identified by an earlier execution step, for example by installing or otherwise providing a missing dependency so that the failed step can be retried successfully.",
      "source_description": "An observed execution failure caused by a missing or unavailable prerequisite in the environment.",
      "target_description": "A subsequent agent action intended to remedy that failure, such as installing the missing dependency."
    },
    {
      "name": "PLANNED_CONTINGENCY_CONFIRMED_BY_OBSERVATION",
      "definition": "An agent's stated plan includes a contingency or explicit prediction about a possible execution condition, and a later observation or execution result confirms that the anticipated condition holds, activating the planned contingency.",
      "source_description": "An agent plan or thought that states a contingency or expectation about a possible execution condition.",
      "target_description": "A subsequent observation or execution result that confirms the anticipated condition actually holds."
    }
  ]
}

